Tool response:
Tool: create_legal_entity
Description: Create Legal Entity
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "incorporation_state": {
          "type": "string",
          "title": "Incorporation State"
        },
        "entity_type": {
          "type": "string",
          "enum": [
            "C_CORPORATION",
            "S_CORPORATION",
            "LLC",
            "PARTNERSHIP",
            "SOLE_PROPRIETORSHIP"
          ],
          "title": "Entity Type"
        },
        "fiscal_year_end_month": {
          "type": "integer",
          "title": "Fiscal Year End Month"
        },
        "fiscal_year_end_day": {
          "type": "integer",
          "title": "Fiscal Year End Day"
        }
      },
      "required": [
        "name",
        "incorporation_state",
        "entity_type",
        "fiscal_year_end_month",
        "fiscal_year_end_day"
      ]
    }

Tool response:
Tool: create_stock_class
Description: Create Stock Class
Parameters:
    {
      "type": "object",
      "properties": {
        "legal_entity_id": {
          "type": "integer",
          "description": "ID of the legal entity to add the stock class to",
          "title": "Legal Entity Id"
        },
        "name": {
          "type": "string",
          "title": "Name"
        },
        "class_type": {
          "type": "string",
          "enum": [
            "COMMON",
            "PREFERRED",
            "OPTION",
            "WARRANT",
            "OTHER"
          ],
          "title": "Class Type"
        },
        "authorized_shares": {
          "type": "integer",
          "title": "Authorized Shares"
        },
        "par_value": {
          "type": "number",
          "title": "Par Value"
        }
      },
      "required": [
        "legal_entity_id"
      ]
    }
